  let xx=0,yy=0,xy=0;for(const p of outline){const x=p.x-mean.x,y=p.y-mean.y;xx+=x*x;yy+=y*y;xy+=x*y;}
  const angle=.5*Math.atan2(2*xy,xx-yy),ux=Math.cos(angle),uy=Math.sin(angle),vx=-uy,vy=ux;
