  function inside(x,y){let hit=false;for(let i=0,j=polygon.length-1;i<polygon.length;j=i++){const a=polygon[i],b=polygon[j];if((a.v>y)!==(b.v>y)&&x<(b.u-a.u)*(y-a.v)/(b.v-a.v)+a.u)hit=!hit;}return hit;}
