window.thakaaiArtwork.strokeMeshes=window.thakaaiArtwork.shapes.filter(s=>s.stroke&&s.kind!=='vein').map(shape=>{
  const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d',shape.d);
  const length=path.getTotalLength(),closed=/z\s*$/i.test(shape.d),rows=Math.max(16,Math.ceil(length/3)),columns=8,points=[],edges=[];
  function at(d){return path.getPointAtLength(closed?(d+length)%length:Math.max(0,Math.min(length,d)));}
  for(let i=0;i<=rows;i++){
    const d=length*i/rows,p=at(d),a=at(d-.2),b=at(d+.2),len=Math.hypot(b.x-a.x,b.y-a.y)||1,nx=-(b.y-a.y)/len,ny=(b.x-a.x)/len;
    for(let j=0;j<columns;j++){
      const t=j/columns*Math.PI*2,r=shape.width/2;
      points.push({x:p.x+nx*Math.cos(t)*r,y:p.y+ny*Math.cos(t)*r,z:Math.sin(t)*r});
      const n=points.length-1;if(j)edges.push([n-1,n]);if(i)edges.push([n-columns,n]);
      if(j===columns-1)edges.push([n-j,n]);
    }
  }
  return{d:shape.d,stroke:shape.stroke,depth:shape.depth,kind:shape.kind,points,edges};
});
